SELECT application_id
FROM (
    SELECT application_id
    FROM b_sanliuling_collection_details
    WHERE api_code = #{apiCode}
      AND receive_date = #{receiveDate}
      AND clean_status = #{cleanStatus}
      AND phone_label = 'br1'
      AND is_delete = 0
    GROUP BY application_id
    ORDER BY application_id
) t
LIMIT 0, 1000

